package com.eduflow.service;
import com.eduflow.dto.PortalDtos.*; import com.eduflow.entity.*; import com.eduflow.exception.EduFlowException; import com.eduflow.repository.*; import com.eduflow.security.TenantRlsContext;
import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor
public class ParentPortalService {
 private final CenterRepository centers; private final UserRepository users; private final StudentRepository students; private final ParentStudentLinkRepository links; private final CenterMembershipRepository memberships; private final GradeRepository grades; private final AttendanceRepository attendance; private final TenantRlsContext tenantRls; private final AuditLogService audit;
 private void apply(Long centerId){if(centerId==null)throw new EduFlowException(HttpStatus.BAD_REQUEST,"tenant.context.required");Center c=centers.findById(centerId).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"center.not-found"));if(c.getStatus()!=CenterStatus.ACTIVE)throw new EduFlowException(HttpStatus.FORBIDDEN,"tenant.center.inactive");tenantRls.apply(centerId);}
 @Transactional public ParentStudentLink link(Long centerId,Long parentId,Long studentId,Long actorId){apply(centerId);User parent=users.findById(parentId).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"parent.not-found"));Student student=students.findByIdAndCenter_Id(studentId,centerId).filter(s->s.getStatus()==StudentStatus.ACTIVE).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"student.not-found"));Optional<ParentStudentLink> existing=links.findByCenter_IdAndParent_IdAndStudent_Id(centerId,parentId,studentId);if(existing.isPresent()){ParentStudentLink link=existing.get();if(link.isActive())throw new EduFlowException(HttpStatus.CONFLICT,"parent.link.exists");link.setActive(true);link=links.save(link);audit.record(centerId,actorId,"PARENT_LINK_REACTIVATED","ParentStudentLink",link.getId(),"Student "+studentId+" link restored for parent "+parentId);return link;}ParentStudentLink link=links.save(new ParentStudentLink(student.getCenter(),parent,student));audit.record(centerId,actorId,"PARENT_LINK_CREATED","ParentStudentLink",link.getId(),"Student "+studentId+" linked to parent "+parentId);return link;}
 @Transactional(readOnly=true) public List<ParentAccountOption> listParentAccounts(Long centerId){apply(centerId);return memberships.findAllByCenter_IdAndRoleAndStatusAndUser_EnabledTrueAndUser_StatusOrderByUser_LastNameAsc(centerId,Role.PARENT,MembershipStatus.ACTIVE,UserStatus.ACTIVE).stream().map(m->new ParentAccountOption(m.getUser().getId(),m.getUser().getEmail(),m.getUser().getFirstName(),m.getUser().getLastName())).toList();}
 @Transactional(readOnly=true) public List<ParentLinkResponse> listLinks(Long centerId){apply(centerId);return links.findAllByCenter_IdAndActiveTrueOrderByCreatedAtDesc(centerId).stream().map(l->new ParentLinkResponse(l.getId(),l.getParent().getId(),l.getParent().getEmail(),l.getStudent().getId(),l.getStudent().getFirstName()+" "+l.getStudent().getLastName(),l.isActive(),l.getCreatedAt())).toList();}
 @Transactional(readOnly=true) public List<ChildResponse> children(Long centerId,Long parentId){apply(centerId);return links.findAllByCenter_IdAndParent_IdAndActiveTrueOrderByStudent_LastNameAsc(centerId,parentId).stream().map(l->new ChildResponse(l.getStudent().getId(),l.getStudent().getStudentNumber(),l.getStudent().getFirstName(),l.getStudent().getLastName())).toList();}
 @Transactional(readOnly=true) public List<ParentGradeResponse> grades(Long centerId,Long parentId,Long studentId){apply(centerId);requireLink(centerId,parentId,studentId);return grades.findAllByCenter_IdAndStudent_IdOrderByCreatedAtDesc(centerId,studentId).stream().map(g->new ParentGradeResponse(g.getId(),g.getTitle(),g.getScore(),g.getMaxScore(),g.getComment(),g.getCreatedAt())).toList();}
 @Transactional(readOnly=true) public List<ParentAttendanceResponse> attendance(Long centerId,Long parentId,Long studentId){apply(centerId);requireLink(centerId,parentId,studentId);return attendance.findAllByCenter_IdAndStudent_IdOrderByCreatedAtDesc(centerId,studentId).stream().map(a->new ParentAttendanceResponse(a.getId(),a.getLesson().getId(),a.getLesson().getTitle(),a.getStatus(),a.getNote(),a.getCreatedAt())).toList();}
 private void requireLink(Long centerId,Long parentId,Long studentId){links.findByCenter_IdAndParent_IdAndStudent_IdAndActiveTrue(centerId,parentId,studentId).orElseThrow(()->new EduFlowException(HttpStatus.NOT_FOUND,"parent.child.not-found"));}
}
